TP.register({id:"lp6-gk",lp:6,grade:"K",mode:"curriculum",checks:5,nextGrade:"1st grade",build(E){const F=E.F;const HOUSE="cabin",TREE="tree",PINE="pine",BRIDGE="bridge",STAR="star",MOON="moon",SPARK="burst",OWL="owl",CAT="cat",BIRD="bluebird",BOOT="boot",HAT="topHat",BED="bed",SCOPE="telescope",COCOA="cocoa",BOOK="books",EAR="ear",TALK="speak",CLAP="hand",PHONE="phone";const ic=(e,px)=>(F.icon||F.pic2)(e,px)||e;const unit=(e,px,sp)=>`<span style="display:inline-block;margin-right:${sp}">${(F.icon||F.pic2)(e,px)||e}</span>`;const TOWN="At the start of every new year the people in a little town by a river hang paper lanterns on a long rope. The rope goes right across the main street, from one pole to the other. They light the lanterns one at a time, starting at the pole by the bakery. When the last one is lit, the whole street glows warm and gold. Children stay up to watch. They stand on the bridge and look down, because the dark water holds the light too, and the lanterns seem to shine twice.";const MOON_FACTS="The moon is the big round light you see in the night sky. The moon does not make any light of its own. The sun is what makes it bright. Sunlight falls on the moon, and the moon sends some of that light down to us. That is why the moon can look silver on a dark night. The moon travels all the way around the earth, over and over, and it takes about a month to go around one time.";const NAME_LETTERS=["M","n","R","e","L","b","T","i","D","d"];const SOUND_LETTERS=["t","E","m","p","u","S","l","g","d","n"];const DISP="font-family:var(--font-display);font-weight:800";const WRITE_DIR="Draw and write on your paper. Hold it up when you finish.";const LINE_STYLE="font-size:2.2rem;line-height:1.9;margin:0 auto;width:fit-content";function wordGrid(ws){return`<div style="display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin:6px 0 10px">${ws.map(w=>`<div style="border:3px solid var(--line);border-radius:16px;text-align:center;padding:14px 6px;background:var(--surface);${DISP};font-size:clamp(2rem,6vw,3.4rem)">${w}</div>`).join("")}</div>`}const K_EYE=window.TP_ICON_EYE||((x,y,r)=>`<circle cx="${x}" cy="${y}" r="${r||4.4}" fill="#4A332A"/><circle cx="${x-1.4}" cy="${y-1.7}" r="1.6" fill="#fff"/>`);const K_BLUSH=window.TP_ICON_BLUSH||((x,y)=>`<ellipse cx="${x}" cy="${y}" rx="6.5" ry="4.2" fill="#F49AAB" opacity=".9"/>`);const K_SMILE=window.TP_ICON_SMILE||((x,y,w)=>`<path d="M${x-w} ${y} q${w} ${w} ${w*2} 0" fill="none" stroke="#4A332A" stroke-width="2.6" stroke-linecap="round"/>`);const K_FACE=window.TP_ICON_FACE||((cx,cy,sp,mw)=>K_EYE(cx-sp,cy)+K_EYE(cx+sp,cy)+K_BLUSH(cx-sp-7,cy+9)+K_BLUSH(cx+sp+7,cy+9)+K_SMILE(cx,cy+9,mw||4));const n1=v=>Math.round(v*10)/10;const at=(x,y,k,inner)=>`<g transform="translate(${n1(x)} ${n1(y)}) scale(${n1(k)})">${inner}</g>`;const INK="#6B4A3C",ROSE="#F7A8A0",GOLDL="#FBD873",BRASS="#D9A066",CREAM="#FBF1E4",NIGHT="#453F80",STREET="#5B5496",RIVER="#2C4A8E",RIVER_L="#7E96D6",STARC="#FBF3D6",POLE="#8C86C4",RED="#DE5A48";function lanternShape(x,y,s,c){return TP_LANT(x,y,s/44,c,false)}const lanternSvg=(w,c)=>`<svg viewBox="0 0 ${w} ${Math.round(w*1.5)}" width="${w}" style="vertical-align:middle" role="img" aria-label="a paper lantern">${lanternShape(w*.5,w*.78,w*.9,c)}</svg>`;function grp(e,n,per,sz){const px=Math.round(parseFloat(sz||"2.6rem")*16),one=unit(e,px,".16em"),rows=[];for(let i=0;i<n;i+=per)rows.push(Array(Math.min(per,n-i)).fill(one).join(""));return`<span style="display:inline-block;border:3px solid var(--line);border-radius:18px;padding:10px 14px;background:var(--surface);line-height:1.25;text-align:left;vertical-align:middle" role="img" aria-label="a group of ${n} pictures">${rows.join("<br>")}</span>`}function scatter(e,n,seed){const pts=[];let x=seed,tries=0,gap=64;const rnd=()=>{x=(x*9301+49297)%233280;return x/233280};while(pts.length<n){const p=[40+rnd()*260,44+rnd()*172];if(pts.every(q=>Math.hypot(q[0]-p[0],q[1]-p[1])>gap))pts.push(p);if(++tries>4e3){tries=0;gap-=4}}return`<svg viewBox="0 0 340 260" width="330" role="img" aria-label="a scattered group of ${n} pictures"><rect x="4" y="4" width="332" height="252" rx="22" fill="var(--surface)" stroke="var(--line)" stroke-width="3"/>${pts.map(p=>e==="LANT"?lanternShape(Number(p[0].toFixed(0)),Number(p[1].toFixed(0)),44,GOLDL):F.picXY(Number(p[0].toFixed(0)),Number(p[1].toFixed(0)),e,38)||`<text x="${p[0].toFixed(0)}" y="${p[1].toFixed(0)}" font-size="38" text-anchor="middle" dominant-baseline="central">${e}</text>`).join("")}</svg>`}const DECKS=[];function picDeck(cards,notes){let i=0;const d={reset(){i=0},render(){return`<div style="text-align:center"><p style="margin:0">Card ${i+1} of ${cards.length}</p><div style="margin:14px 0 18px;display:flex;justify-content:center;align-items:center;gap:22px;flex-wrap:wrap">${cards[i]}</div><div class="row center"><button class="btn ghost" data-d="-1" ${i===0?"disabled":""}>Back</button><button class="btn ghost" data-d="1" ${i===cards.length-1?"disabled":""}>Next</button></div></div>`},bind(root,ctx){root.querySelectorAll("[data-d]").forEach(b=>b.onclick=()=>{i=Math.max(0,Math.min(cards.length-1,i+Number(b.dataset.d)));ctx.redraw()})},print(){return`<p><em>Picture cards shown one at a time:</em> ${notes.join(" ")}</p>`}};DECKS.push(d);return d}function lab(x,y,t,sz,c){return`<text x="${x}" y="${y}" font-size="${sz||24}" font-family="Andika,sans-serif" font-weight="700" fill="${c||"var(--ink)"}" text-anchor="middle">${t}</text>`}const nightBox=(w,h)=>`<rect x="3" y="3" width="${w-6}" height="${h-6}" rx="22" fill="${NIGHT}" stroke="var(--line)" stroke-width="4"/>`;const skyDots=(w,n,seed)=>{let x=seed||11,out="";const rnd=()=>{x=(x*9301+49297)%233280;return x/233280};for(let i=0;i<n;i++)out+=`<circle cx="${(18+rnd()*(w-36)).toFixed(0)}" cy="${(16+rnd()*96).toFixed(0)}" r="${i%3?2:2.6}" fill="${STARC}" opacity="${i%2?".8":".95"}"/>`;return out};const streetBand=(w,top,h)=>`<rect x="8" y="${top}" width="${w-16}" height="${h}" fill="${STREET}"/>`;const ripple=(x0,x1,y,w,op)=>{const n=Math.max(1,Math.round((x1-x0)/44)),seg=(x1-x0)/n;let d=`M${x0} ${y} q${(seg/2).toFixed(1)} -8 ${seg.toFixed(1)} 0`;for(let i=1;i<n;i++)d+=` t${seg.toFixed(1)} 0`;return`<path d="${d}" fill="none" stroke="${RIVER_L}" stroke-width="${w}" stroke-linecap="round" opacity="${op}"/>`};const riverBand=(x0,x1,top,h)=>`<rect x="${x0}" y="${top}" width="${x1-x0}" height="${h}" fill="${RIVER}"/>`+ripple(x0,x1,top+16,3.2,".8");function poleG(x,baseY,h,c){return`<path d="M${x} ${baseY} V${baseY-h}" stroke="${POLE}" stroke-width="10" stroke-linecap="round"/>`+lanternShape(x,baseY-h-20,50,c||GOLDL)}function townFig(){const w=620,h=300,base=232;let b=nightBox(w,h)+skyDots(w,12,19);b+=streetBand(w,base,h-base-11)+riverBand(452,w-8,base,h-base-11);b+=F.picXY(120,base-54,HOUSE,120)+F.picXY(258,base-48,TREE,96)+F.picXY(258,base-10,CAT,56);b+=poleG(368,base,88,ROSE);b+=F.picXY(532,base-2,BRIDGE,124);b+=lab(120,h-20,"house",22,CREAM)+lab(258,h-20,"tree",22,CREAM)+lab(368,h-20,"pole",22,CREAM)+lab(532,h-20,"bridge",22,CREAM);return`<svg viewBox="0 0 ${w} ${h}" width="600" role="img" aria-label="A town street at night. A house is on the left, then a tree with a cat sitting under it, then a pole with a pink lantern on top, and on the right a bridge over the river.">${b}</svg>`}function polesFig(){const w=360,h=300,base=236;let b=nightBox(w,h)+skyDots(w,8,31)+streetBand(w,base,h-base-11);b+=poleG(110,base,70,GOLDL)+poleG(250,base,150,ROSE);b+=lab(110,h-20,"Pole 1",24,CREAM)+lab(250,h-20,"Pole 2",24,CREAM);return`<svg viewBox="0 0 ${w} ${h}" width="340" role="img" aria-label="Two lantern poles standing on the same street. Pole 1 is short and Pole 2 is tall.">${b}</svg>`}function ropesFig(){const w=440,h=210;let b=`<rect x="3" y="3" width="${w-6}" height="${h-6}" rx="22" fill="var(--surface)" stroke="var(--line)" stroke-width="4"/>`;b+=`<path d="M60 26 V${h-26}" stroke="var(--line)" stroke-width="3" stroke-dasharray="7 6"/>`;b+=`<path d="M64 76 H214" stroke="${BRASS}" stroke-width="11" stroke-linecap="round"/>`+lab(139,110,"Rope A",24);b+=`<path d="M64 148 H392" stroke="${BRASS}" stroke-width="11" stroke-linecap="round"/>`+lab(228,182,"Rope B",24);return`<svg viewBox="0 0 ${w} ${h}" width="420" role="img" aria-label="Two ropes. Rope A is short and Rope B is long. Both start at the same dotted line on the left.">${b}</svg>`}function linesFig(){const tagP=e=>`<span style="line-height:1" aria-hidden="true">${ic(e,40)}</span>`;const line=(a,t,b)=>`<div style="display:flex;align-items:center;justify-content:space-between;gap:16px">${tagP(a)}<span style="${DISP};font-size:clamp(1.7rem,4.4vw,2.9rem);flex:1;text-align:left">${t}</span>${tagP(b)}</div>`;return`<div style="width:fit-content;margin:8px auto 10px;border:6px solid var(--gold-ink);border-radius:16px;background:var(--surface);padding:12px 22px;display:grid;gap:10px">${line(BOOT,"We walk down the street.",BRIDGE)}${line(MOON,"The lantern is gold.",STAR)}</div><p class="small" style="text-align:center">The four pictures are a boot, a bridge, the moon, and a star.</p>`}function packChart(){const rows=[[lanternSvg(44,ROSE),"lantern"],[SCOPE,"telescope"],[COCOA,"cocoa"]];const right=["hangs on the rope","look at the stars","warms your hands"];const cell=(pic,word)=>`<span style="display:inline-block;text-align:center;min-width:110px"><span style="display:block;line-height:1.1" aria-hidden="true">${ic(pic,48)}</span><span style="display:block;font-family:var(--font-display);font-weight:700;font-size:1.3rem">${word}</span></span>`;const words=t=>`<span style="display:inline-block;max-width:170px;font-family:var(--font-display);font-weight:700;font-size:1.25rem;text-align:left">${t}</span>`;return`<div class="figure" style="gap:16px;flex-direction:column" role="img" aria-label="Picture chart: a lantern hangs on the rope, a telescope is for looking at the stars, a cup of cocoa warms your hands">`+rows.map((r,i)=>`<div style="display:flex;align-items:center;gap:10px;border:3px solid var(--line);border-radius:18px;padding:10px 16px;background:var(--surface)">${cell(r[0],r[1])}<span style="font-size:2rem;font-weight:800;color:var(--sea)" aria-hidden="true">&#8594;</span>${words(right[i])}</div>`).join("")+`</div>`}function matchFig(){const box=(a,b)=>`<div style="border:3px solid var(--line);border-radius:18px;background:var(--surface);padding:10px 18px;text-align:left;line-height:1.5">${a}<br>${b}</div>`;const row=(e,n,sp)=>`<span aria-hidden="true">${Array(n).fill(unit(e,42,sp)).join("")}</span>`;const tagT=t=>`<p class="fig-label" style="margin:0 0 2px;text-align:left">${t}</p>`;return`<div style="display:grid;gap:12px;justify-content:center;margin:6px 0 12px"><div>${tagT("Top box")}${box(row(lanternSvg(40,ROSE),5,".12em"),row(STAR,7,".12em"))}</div><div>${tagT("Bottom box")}${box(row(HOUSE,6,".02em"),row(TREE,6,".55em"))}</div></div>`}function ropeRow(n){const w=620,h=150,x0=40,x1=w-40,sag=22,ry=x=>{const t=(x-x0)/(x1-x0);return 44+4*sag*t*(1-t)};let b=`<rect x="3" y="3" width="${w-6}" height="${h-6}" rx="22" fill="${NIGHT}" stroke="var(--line)" stroke-width="4"/>`+skyDots(w,6,7);b+=`<path d="M${x0} 44 Q${(x0+x1)/2} ${44+2*sag} ${x1} 44" fill="none" stroke="${INK}" stroke-width="5" stroke-linecap="round"/>`;const cols=[ROSE,GOLDL,"#C9A6EC","#9FD6F0","#F6B3D0"];for(let i=0;i<n;i++){const x=x0+(i+.5)*(x1-x0)/n;b+=lanternShape(x,ry(x)+26,44,cols[i%5])}return`<svg viewBox="0 0 ${w} ${h}" width="600" role="img" aria-label="A rope across the street with ${n} paper lanterns hanging from it">${b}</svg>`}function windowsFig(n,seed){const w=620,h=230;let b=`<rect x="3" y="3" width="${w-6}" height="${h-6}" rx="22" fill="var(--surface)" stroke="var(--line)" stroke-width="4"/>`;b+=`<rect x="30" y="28" width="250" height="150" rx="18" fill="${CREAM}" stroke="${INK}" stroke-width="4"/>`;b+=`<path d="M155 28 V178" stroke="${INK}" stroke-width="4"/>`;b+=lab(155,216,"two windows",22);const cols=[GOLDL,ROSE];for(let i=0;i<n;i++){const x=340+i%4*68,y=74+Math.floor(i/4)*84;b+=lanternShape(x,y,54,cols[Math.floor(i/4)%2])}b+=lab(470,216,"the lanterns",22);return`<svg viewBox="0 0 ${w} ${h}" width="600" role="img" aria-label="A house with two empty windows on the left, and ${n} paper lanterns waiting beside it">${b}</svg>`}function bookFig(){return`<p class="passage" style="${LINE_STYLE}">I see a town.<br>The sky is dark.<br>I see a lamp.<br>It is on.<br>The lamp is red.<br>I can see the lamp.<br>It is not dim.<br>I like the lamp.</p><div class="figure" style="gap:14px" aria-hidden="true">${ic(HOUSE,48)}${ic(MOON,48)}${lanternSvg(42,GOLDL)}</div><p class="small">A lamp gives light. A lantern is a lamp. It is paper. It hangs on rope.</p>`}function unitFig(){const u=46,y1=56,y2=150;let s=`<svg viewBox="0 0 420 212" width="400" role="img" aria-label="A rope above five blocks laid end to end, and a pole above three blocks laid end to end.">`;s+=`<path d="M40 ${y1-8} h${5*u}" stroke="${BRASS}" stroke-width="9" stroke-linecap="round" fill="none"/>`;for(let i=0;i<5;i++)s+=`<rect x="${40+i*u}" y="${y1+4}" width="${u}" height="26" fill="${GOLDL}" stroke="${INK}" stroke-width="2.5"/>`;s+=lab(312,y1+24,"rope",24);s+=`<path d="M40 ${y2-14} h${3*u}" stroke="${POLE}" stroke-width="9" stroke-linecap="round" fill="none"/>`;for(let i=0;i<3;i++)s+=`<rect x="${40+i*u}" y="${y2}" width="${u}" height="26" fill="${GOLDL}" stroke="${INK}" stroke-width="2.5"/>`;s+=lab(232,y2+20,"pole",24);s+=`<text x="40" y="202" font-size="20" font-family="Andika,sans-serif" font-weight="700" fill="var(--muted)">Every block is the same size.</text>`;return s+"</svg>"}const PURPLE="#8E5BC9",BLUE="#2F7FD9",GREEN="#3FA34D",YELLOW="#F2C01E",ORANGE="#E08A3C";const SHP=`stroke="${INK}" stroke-width="4" stroke-linejoin="round"`;function teenFig(n){const w=620,h=232;let b=`<rect x="3" y="3" width="${w-6}" height="${h-6}" rx="22" fill="var(--surface)" stroke="var(--line)" stroke-width="4"/>`;b+=`<rect x="24" y="24" width="300" height="152" rx="18" fill="${CREAM}" stroke="${INK}" stroke-width="4"/>`;for(let i=0;i<10;i++)b+=lanternShapeS(58+i%5*58,70+Math.floor(i/5)*64,46,GOLDL);b+=lab(174,206,"one full rope",22);for(let i=0;i<n-10;i++)b+=lanternShapeS(376+i%5*52,70+Math.floor(i/5)*64,46,ROSE);b+=lab(470,206,"extra lanterns",22);return`<svg viewBox="0 0 ${w} ${h}" width="600" role="img" aria-label="A box holding one full rope of ten gold lanterns, and ${n-10} extra pink lanterns standing beside the box">${b}</svg>`}const TRAY_K=["L","P","S","P","L","S","P","L","P","S","L","P","P","L"];function trayK(){const w=620,h=270;let b=`<rect x="3" y="3" width="${w-6}" height="${h-6}" rx="22" fill="var(--surface)" stroke="var(--line)" stroke-width="4"/>`;TRAY_K.forEach((t,i)=>{const x=50+i%5*110+55,y=66+Math.floor(i/5)*80;b+=t==="L"?lanternShape(x,y,46,ROSE):F.picXY(x,y,t==="S"?STAR:PINE,52)||""});return`<svg viewBox="0 0 ${w} ${h}" width="600" role="img" aria-label="A tray with paper lanterns, stars and pine trees mixed together">${b}</svg>`}function shapeHouseFig(){const w=620,h=340,base=286;let b=nightBox(w,h)+skyDots(w,9,23)+streetBand(w,base,h-base-11);b+=`<circle cx="180" cy="60" r="42" fill="${YELLOW}" ${SHP}/>`;b+=`<polygon points="180,120 270,190 90,190" fill="${PURPLE}" ${SHP}/>`;b+=`<rect x="100" y="190" width="160" height="96" fill="${CREAM}" ${SHP}/>`;b+=`<rect x="124" y="210" width="54" height="54" fill="${BLUE}" ${SHP}/>`;b+=`<rect x="204" y="216" width="40" height="70" fill="${GREEN}" ${SHP}/>`;b+=poleG(400,base,70,ROSE);b+=lab(180,h-14,"house",22,CREAM)+lab(400,h-14,"lantern pole",22,CREAM);return`<svg viewBox="0 0 ${w} ${h}" width="600" role="img" aria-label="A house at night drawn from plain shapes: a purple triangle roof, a blue square window, a green rectangle door, a round yellow moon in the sky above the house, and a lantern pole standing beside the house.">${b}</svg>`}function flatSolidFig(){const w=820,h=256;let b="";const card=(i,inner,lab2)=>{const x=16+i*200;return`<rect x="${x}" y="10" width="180" height="180" rx="20" fill="var(--surface)" stroke="var(--line)" stroke-width="4"/><g transform="translate(${x} 10)">${inner}</g><text x="${x+90}" y="226" font-size="26" font-family="Andika,sans-serif" font-weight="700" text-anchor="middle" fill="var(--muted)">${lab2}</text>`};b+=card(0,`<circle cx="90" cy="90" r="56" fill="${YELLOW}" ${SHP}/>`,"1");b+=card(1,`<polygon points="34,62 90,34 146,62 146,130 90,158 34,130" fill="${BLUE}" ${SHP}/><path d="M34 62 L90 90 L146 62 M90 90 V158" fill="none" ${SHP}/>`,"2");b+=card(2,`<polygon points="90,34 152,146 28,146" fill="${GREEN}" ${SHP}/>`,"3");b+=card(3,`<path d="M34 54 v82 a56 22 0 0 0 112 0 V54 Z" fill="${ORANGE}" ${SHP}/><ellipse cx="90" cy="54" rx="56" ry="22" fill="#F3B877" ${SHP}/>`,"4");return`<svg viewBox="0 0 ${w} ${h}" width="800" role="img" aria-label="Four cards. Card 1 is a yellow circle drawn flat on the card. Card 2 is a blue box drawn so you can see three of its sides. Card 3 is a green triangle drawn flat on the card. Card 4 is an orange can with a round lid you can see into.">${b}</svg>`}const VS=`<span style="${DISP};font-size:1.5rem;color:var(--muted)" aria-hidden="true">and</span>`;const LANT_S=lanternSvg(40,ROSE),LANT_B=lanternSvg(56,GOLDL);const cmp=picDeck([grp(LANT_S,6,3,"2.6rem")+VS+grp(STAR,8,4,"2.6rem"),scatter(HOUSE,7,13)+VS+scatter(TREE,5,29),grp(MOON,4,2,"3.4rem")+VS+grp(STAR,7,4,"1.7rem"),grp(SPARK,8,4,"2.6rem")+VS+grp(LANT_S,8,4,"2.6rem"),grp(STAR,9,5,"2.6rem")+VS+scatter("LANT",10,41)],["1) 6 lanterns and 8 stars.","2) 7 houses and 5 trees, mixed up.","3) 4 big moons and 7 small stars.","4) 8 sky sparks and 8 lanterns.","5) 9 stars and 10 lanterns."]);const STOPS=[{id:1,title:"Lantern Tag Letters",short:"Tag Letters",parts:[{title:"Name the Letter",std:["RF.K.1"],kind:"words",full:E.alphabet(),words:NAME_LETTERS,unit:"Letter",n:10,dur:45,dir:"Say the name of each letter.",desc:"naming uppercase and lowercase letters, including look-alike letters",key:["The student says the name of each letter: M, n, R, e, L, b, T, i, D, d. Count a letter correct when the name is right. Sounds are not needed here.","Watch the look-alike pair b and d, which are the sixth card and the last card. Capital D and lowercase d share one name, so you can hear whether the child knows both shapes. Write down any letters that were missed or mixed up."]},{title:"Two Lines",std:["RF.K.1"],n:3,dur:35,dir:"Look at the two lines. Answer out loud.",desc:"print concepts (counting words and letters)",html:()=>linesFig(),key:["Ask: How many words are in the top line? (5)","Ask: How many words are in the bottom line? (4)","Ask: Look at the first word in the bottom line. How many letters does it have? (3, the word The)"]}]},{id:2,title:"Count the Lantern Rope",short:"Count",parts:[{title:"Up the Street",std:["K.CC.A.1"],n:3,label:"checks met",dur:75,dir:"Count out loud. Start at 1. Go as high as you can.",desc:"counting out loud by ones",html:()=>`<p class="big" style="text-align:center">The town is hanging lanterns all the way down the main street. Count out loud as the lanterns go up.</p><div class="figure">${ic("lantern",118)}</div>`,key:["Say: Start at 1 and count as high as you can. Check: counts 1 to 20 in order with no skips.","Keeps going from 20 to 40 and gets across each new ten (29 to 30, 39 to 40).","Counts past 50. Stop the student at 100. Write the highest number said before a mistake. The end of year goal is 100."]},{title:"Ten to a Rope",std:["K.CC.A.1"],n:2,label:"checks met",dur:45,dir:"Count by tens out loud.",desc:"counting by tens",html:()=>`<div class="figure">${lanternSvg(70,GOLDL)}${lanternSvg(70,ROSE)}</div><p class="big" style="text-align:center">Each rope holds 10 lanterns. Count by tens to 100.</p>`,key:["Say: Count the lanterns by tens as each rope goes up. Check: says 10, 20, 30, 40, 50 with no help.","Keeps going: 60, 70, 80, 90, 100. Write the last number said in order."]}]},{id:3,title:"Quiet Street Sounds",short:"Sounds",parts:[{title:"Rhyme and Clap",std:["RF.K.2"],n:6,dur:60,dir:"Listen to your teacher. Answer out loud.",desc:"hearing rhymes, making a rhyme, and clapping syllables",html:()=>`<div class="figure">${F.pic(EAR)}${F.pic(CLAP)}</div><p class="small" style="text-align:center">A lantern is a little paper light you hang up.</p>`,key:["Ask: Do night and light rhyme? (yes)","Ask: Do moon and star rhyme? (no)","Ask: Which word does not rhyme: sky, high, town? (town)","Say: Tell me a word that rhymes with bright. (night, light, kite, right, white. Silly words count.)","Say: Clap the parts in lantern. (2 claps: lan-tern)","Say: Clap the parts in telescope. (3 claps: tel-e-scope)"]},{title:"Put It Together",std:["RF.K.2"],n:6,dur:60,dir:"Listen to your teacher. Answer out loud.",desc:"blending spoken sounds and saying the first, last, and all sounds in a word",html:()=>`<div class="figure">${F.pic(TALK)}${F.pic(STAR)}</div>`,key:["Say: Put these sounds together: /m/ /oo/ /n/. (moon)","Say: Put these sounds together: /s/ /t/ /ar/. (star)","Ask: What is the first sound in town? (/t/. The sound, not the letter name.)","Ask: What is the first sound in night? (/n/)","Ask: What is the last sound in lamp? (/p/)","Say: Tell me every sound in sky. (/s/ /k/ /ie/, three sounds)"]}]},{id:4,title:"Bo and the Lamp",short:"Bo Story",parts:[{std:["RL.K.1"],n:4,dur:90,dir:"Listen while your teacher reads the lines. Then answer out loud.",desc:"asking and answering questions about key details in a story read aloud to the student",html:()=>`<div class="figure" aria-hidden="true">${lanternSvg(80,GOLDL)}${ic(BRIDGE,64)}</div><p class="passage" style="${LINE_STYLE}">Bo has a lamp.<br>Bo sits on the bridge.<br>The sky is dark.<br>Bo sees a big star.</p><p class="small">A bridge sits on the river. You can walk on it.</p>`,key:["Read the four lines on the screen out loud to the student two times. Point under each word as you read. The student does not read them. Ask: Who is the story about? (Bo)","Ask: Where does Bo sit? (on the bridge)","Ask: What does Bo see? (a big star)","Say: Now you ask me a question about Bo. Start with What or Where. (asks a real question about the lines, such as: Where is Bo's lamp?)"]}]},{id:5,title:"Two Ropes to Compare",short:"Compare",parts:[{title:"More or Fewer",std:["K.CC.C.6"],n:5,dur:75,dir:"Look at the two groups. Answer out loud.",desc:"comparing two groups of objects (more, fewer, the same)",render:()=>cmp.render(),bind:(root,ctx)=>cmp.bind(root,ctx),printHtml:()=>cmp.print(),key:["Card 1. Ask: Are there more lanterns or more stars? (stars. 8 is more than 6.)","Card 2. Ask: Which group has fewer, the houses or the trees? (the trees. 5 is fewer than 7.)","Card 3. Say: The moons are big and the stars are small. Ask: Which group has more? (the stars. 7 is more than 4. Size does not change the count.)","Card 4. Ask: Are there more sky sparks, more lanterns, or the same? (the same, 8 and 8)","Card 5. Ask: Which group has fewer, the stars or the lanterns? (the stars. 9 is fewer than 10.)"]},{title:"One for Each",std:["K.CC.C.6"],dur:60,dir:"Look at the boxes. Answer out loud.",desc:"matching and counting to tell which group has more, fewer, or the same",fig:()=>matchFig(),qs:["Look at the top box. Is there a star for every lantern?","In the top box, which has more: the lanterns or the stars?","In the top box, which has fewer: the lanterns or the stars?","Look at the bottom box. Are there more houses, more trees, or the same?"],key:["Yes. There are 5 lanterns and 7 stars, so 2 stars are left over.","The stars (7 is more than 5)","The lanterns (5 is fewer than 7)","The same, 6 and 6. The trees are spread out, but the count is equal."]}]},{id:6,title:"Sky Spark Words",short:"Spark Words",parts:[{title:"Letter Sounds",std:["RF.K.3"],kind:"words",words:SOUND_LETTERS,unit:"Letter",n:10,dur:45,dir:"Say the sound each letter makes.",desc:"saying the sounds of letters",key:["The student says the most common sound for each letter: t /t/, E as in egg, m /m/, p /p/, u as in up, S /s/, l /l/, g /g/, d /d/, n /n/. The letter name is not needed here.","The long sound for E or u is also fine. Write down any sounds that were missed."]},{title:"Night Words",std:["RF.K.3"],n:9,dur:60,dir:"Read each word out loud.",desc:"reading high-frequency words and short vowel words",html:()=>wordGrid(["we","go","like","at","is","sun","log","net","hum"]),key:["High-frequency words the student should know by sight: we, go, like, at, is","Sounds out or reads: sun, log, net, hum","Score is the number of words read correctly out of 9. Write down which ones were missed."]}]},{id:7,title:"Listen to the Town",short:"Listen",parts:[{std:["SL.K.2"],n:5,dur:75,dir:"Put your eyes on your teacher and listen. Then answer out loud.",desc:"answering questions about key details in a text read aloud and asking for help",html:()=>`<div class="figure">${F.pic(EAR)}${lanternSvg(74,ROSE)}</div><p class="big" style="text-align:center">Listening time. Your teacher will read you a report from the town by the river.</p>`,read:TOWN,key:["Ask: What do the people hang on the long rope? (paper lanterns)","Ask: Where does the rope go? (right across the main street, from one pole to the other)","Ask: Which pole do they start lighting from? (the pole by the bakery)","Ask: Why do the lanterns seem to shine twice? (the dark water of the river holds the light too)","Say: Pretend you missed one part. What can you say to me? (asks for help, such as: Can you read that part again? or What is a pole?)"]}]},{id:8,title:"Lanterns on the Bridge",short:"Add It",parts:[{std:["K.OA.A.2"],n:5,dur:110,dir:"Listen to each story. You can draw on your paper. Say your answer out loud.",desc:"addition and subtraction word problems within 10, with drawings",html:()=>`<div class="figure">${ropeRow(5)}</div><p class="small" style="text-align:center">You can draw a circle for each lantern on your paper, then count or cross out.</p>`,key:["Say: 4 lanterns hang on the bridge rail. 3 more go up beside them. How many lanterns are on the rail now? (7. 4 + 3 = 7)","Say: 8 stars were out. Then 2 of them went behind a cloud. How many stars can you still see? (6. 8 - 2 = 6)","Say: 5 lanterns are lit. Then 4 more get lit. How many are lit now? (9. 5 + 4 = 9)","Say: There are 10 lanterns on the rope. 3 of them are not lit yet. How many are lit? (7. 10 - 3 = 7)","Say: 2 owls sit on the roof and 5 owls sit in the tree. How many owls in all? (7. 2 + 5 = 7)","Drawing, fingers, or counters all count. Note whether the student counted every one from 1 or counted on from the bigger number."]}]},{id:9,title:"Two Windows",short:"Break It",parts:[{std:["K.OA.A.3"],n:5,dur:95,dir:"Look at the lanterns. Put some in each window. Answer out loud.",desc:"breaking numbers up to 10 into two parts in more than one way",fig:()=>F.row(windowsFig(5,3)),fig2:()=>F.row(windowsFig(8,7)),qs:["Look at the first picture. There are 5 lanterns and 2 windows. Say one way to put them in the two windows. Say it like this: ____ and ____ makes 5.","Now tell me a different way to make 5.","Look at the second picture. Count the lanterns there. How many?","Say one way to put those lanterns in the two windows.","Now tell me a different way to make that same number."],key:["Any true pair for 5: 4 and 1, 3 and 2, 2 and 3, 1 and 4, 5 and 0. The student has to say both parts.","A different true pair for 5 than the first one. Saying the same pair backwards (3 and 2, then 2 and 3) counts as different only if the student points to which window each part goes in.","8 lanterns","Any true pair for 8: 7 and 1, 6 and 2, 5 and 3, 4 and 4, and so on.","A second, different true pair for 8. If the student is stuck, say: You put 5 in this window. How many are left for the other one? and count with them.","Writing it as 5 = 3 + 2 is a bonus, not a requirement. Saying the two parts out loud is enough at this grade."]}]},{id:10,title:"Tall and Long",short:"Tall Long",parts:[{std:["K.MD.A.2"],n:5,dur:75,dir:"Look at the two poles and the two ropes. Answer out loud.",desc:"comparing two objects to tell which has more or less of an attribute and describing the difference",html:()=>`<div class="figure">${polesFig()}${ropesFig()}</div><p class="small" style="text-align:center">Both poles stand on the same street, and both ropes start at the same dotted line, so you can see which one is bigger.</p>`,key:["Ask: Which lantern pole is taller? (Pole 2)","Ask: Which lantern pole is shorter? (Pole 1)","Ask: Which rope is longer? (Rope B)","Ask: Which rope is shorter? (Rope A)","Say: Tell me about the two poles in one sentence. Use the word taller. (describes the difference, such as: Pole 2 is taller than Pole 1.)"]}]},{id:11,title:"Little Night Book",short:"Night Book",parts:[{std:["RF.K.4"],n:32,label:"words read correctly",dur:60,dir:"Point to each word and read it out loud.",desc:"reading a short emergent-reader book with purpose and understanding",html:()=>bookFig(),key:["Count the words the student reads correctly, out of 32, and enter the number in the box. A word the student fixes without help counts. Write down the words that were missed.","Points or tracks under each word, left to right and top to bottom","Reads most of the words correctly, including the sight words I, see, the, is, a. Picture words, carried by the picture beside them: town, dark. The rest are sight words or sound-out words (sky, lamp, dim)","Ask: What is this little book about? (the town at night, or a lamp that is on)"]}]},{id:12,title:"Moon Watch",short:"Moon",parts:[{std:["RI.K.1"],n:6,dur:90,dir:"Listen while your teacher reads the lines. Then answer out loud.",desc:"asking and answering questions about key details in an informational text about the moon",html:()=>`<div class="figure" aria-hidden="true">${ic(MOON,54)}${ic("sun",54)}</div><p class="passage" style="${LINE_STYLE}">The moon is in the sky.<br>The moon is not hot.<br>The moon has no light.<br>The sun shines on it.<br>That is why it looks bright.<br>Some nights you see a bit.</p>`,read:MOON_FACTS,key:["Read the six lines on the screen out loud to the student two times. Point under each word as you read. The student does not read them. Ask: Where is the moon? (in the sky. Line 1.)","Ask: Is the moon hot? (no. Line 2.)","Ask: Does the moon make its own light? (no. Line 3 says the moon has no light.)","Ask: What shines on the moon? (the sun. Line 4.)","Ask: Why does the moon look bright? (because the sun shines on it. Line 5.)","Say: Ask me a question about the moon. Start with What or Where. (asks a real question about the moon)","All six scored items come from the lines on the screen. After you score them you may read the longer moon text aloud for interest. It is not scored here."]}]},{id:13,title:"Town Talk",short:"Talk",parts:[{std:["L.K.1"],n:5,dur:75,dir:"Look at the picture. Listen to your teacher. Say your answer out loud.",desc:"spoken grammar items (plural nouns, question words, position words in complete sentences)",html:()=>`<div class="figure">${townFig()}</div>`,key:["Say: One lantern, two ____. (lanterns)","Say: One box, two ____. (boxes)","Say: Ask me a question that starts with Where. (asks a where question)","Say: Look at the picture. Where is the cat? Tell me in a whole sentence. (a complete sentence with under, such as: The cat is under the tree.)","Say: Where is the lantern? Tell me in a whole sentence. (a complete sentence with on or on top of, such as: The lantern is on the pole.)"]}]},{id:14,title:"New Year Notebook",short:"Write",parts:[{wk:"opinion",alt:{group:"write",label:"Bridge or Street",icon:"💬",hint:"Draw it and tell what you think"},std:["W.K.1"],n:3,label:"checks met",dur:150,dir:WRITE_DIR,desc:"a draw-and-write opinion piece about the bridge or the lantern street",html:()=>`<div class="figure">${ic(BRIDGE,64)}${lanternSvg(56,ROSE)}</div><p class="big">Would you rather watch the night sky from the bridge, or walk down the street under the lanterns? Draw the one you pick. Write or tell what you think and why.</p>`,key:["Tells the reader what the choice is about: the bridge or the lantern street (W.K.1)","States an opinion, which one the student would pick. Drawing, telling, or writing all count (W.K.1)","Gives a reason or a detail for the pick, such as: I like the water, or It is bright there (W.K.1)"]},{wk:"facts",alt:{group:"write",label:"Night Facts",icon:"📖",hint:"Draw it and tell one true thing"},std:["W.K.2"],n:3,label:"checks met",dur:150,dir:WRITE_DIR,desc:"a draw-and-write informative piece about a lantern, an owl, or the moon",html:()=>`<div class="figure">${lanternSvg(56,GOLDL)}${ic(OWL,56)}${ic(MOON,56)}</div><p class="big">Pick one: a lantern, an owl, or the moon. Draw it. Write its name. Then write or tell one true thing about it.</p><p class="small">An owl is a bird. It is awake at night. A lantern is a paper light. You hang it up.</p>`,key:["Names what the drawing and writing are about: a lantern, an owl, or the moon. The student may say it, label the picture, or write a letter or word for it (W.K.2)","Gives at least one piece of true information about it, such as: A lantern glows. An owl is awake at night. The moon is in the sky (W.K.2)","Uses drawing, telling, or writing (any mix) to get the information across (W.K.2)"]},{wk:"story",alt:{group:"write",label:"My Night Story",icon:"✏",hint:"Draw and tell what happened"},std:["W.K.3"],n:4,label:"checks met",dur:150,dir:WRITE_DIR,desc:"a draw-and-write story about a time outside in the dark, told in order with a reaction",html:()=>`<div class="figure">${ic(MOON,56)}${ic(HAT,56)}${ic(BOOT,56)}</div><p class="big">Think of a time you were outside when it was dark. Draw what happened. Then tell what happened first and what happened next. Tell how you felt.</p>`,key:["Tells about one real thing that happened, not a list of facts (W.K.3)","Tells two parts, a first and a next, in the order they happened (W.K.3)","Gives at least one detail about it, such as where it was or who was there (W.K.3)","Reacts to what happened, such as: It was fun, or I was cold, or I liked it (W.K.3)"]}]},{id:15,title:"Night Walk List",short:"The List",parts:[{std:["W.K.8"],dur:60,dir:"Look at the chart. Answer out loud.",desc:"answering questions from a picture chart and from experience",fig:()=>packChart(),qs:["Look at the chart. What hangs on the rope?","Look at the chart. What do we use to look at the stars?","Look at the chart. What warms your hands?","Think about last night. What is one thing you did before you went to bed?"],key:["The lantern. Uses the chart to answer.","The telescope. Uses the chart to answer.","The cocoa, the warm drink. Uses the chart to answer.","Names one real thing, such as brushed my teeth, read a book, or put on pajamas. Recalls it from experience."]}]},{id:16,title:"Tell Me More",short:"Tell More",parts:[{std:["SL.K.4"],n:3,label:"checks met",dur:60,dir:"Tell your teacher out loud. Use lots of details.",desc:"describing a familiar thing you do, with details",html:()=>`<div class="figure">${F.pic(BED)}${F.pic(BOOK)}${F.pic(COCOA)}</div><p class="big" style="text-align:center">Tell me about something you do right before bed.</p>`,key:["Names the thing and tells something about it","Adds a detail when you ask: Where do you do it?","Adds another detail when you ask: Who is with you, and what do you say or hear?"]}]},{id:17,title:"How Many on the Rope",short:"How Many",parts:[{title:"Count and Tell",std:["K.CC.B.4"],n:3,dur:60,dir:"Count the lanterns out loud. Then answer out loud.",desc:"counting a group and telling how many, and counting on by one",fig:()=>F.row(ropeRow(7)),qs:["Point to each lantern and count out loud. How many lanterns are on the rope?","I will ask it again. How many lanterns are on the rope?","One more lantern goes up on the rope. How many are there now?"],key:["7. One number word for each lantern, left to right, with no skips and no double counts.","7, said straight back without counting again. The last number you say when you count tells how many there are. Having to start the count over is worth a note.","8. Look for counting on from 7. Starting again at 1 still gets the right answer, so count it correct, but write down that the student recounted."]},{title:"Ten and Some More",std:["K.NBT.A.1"],n:3,dur:70,dir:"Look at the full rope and the extra lanterns. Answer out loud.",desc:"seeing a teen number as ten ones and some more ones",fig:()=>F.row(teenFig(14)),fig2:()=>F.row(teenFig(17)),qs:["Look at the first picture. The box holds one full rope. How many lanterns are in the box, and how many extra ones are beside it?","So how many lanterns are there in all? Say it this way: ten and ____ more.","Look at the second picture. How many lanterns in all, and how many is that as ten and some more?"],key:["10 in the box and 4 extra. The box always holds exactly 10.","14. Ten and 4 more. Writing 14 = 10 + 4 is a bonus, not a requirement.","17. Ten and 7 more. If the student counts all 17 one at a time instead of starting from the full box of 10, the answer still counts, but note that the ten was not used."]}]},{id:18,title:"Sort the Night Tray",short:"Sort",parts:[{std:["K.MD.B.3"],n:4,dur:70,dir:"Look at the tray. Answer out loud.",desc:"sorting a mixed group into three given categories, counting each one, and ordering the categories by count",fig:()=>F.row(trayK()),qs:["The tray holds three kinds of things: lanterns, stars and pine trees. How many lanterns are on the tray?","How many stars?","How many pine trees?","Now put the three groups in order, from the group with the fewest to the group with the most."],key:["5 lanterns","3 stars","6 pine trees","Stars, then lanterns, then pine trees (3, then 5, then 6). The student has to compare the three counts, not just read them back. If the groups are hard to keep straight, let the student touch each one on the screen as it is counted and note that."]}]},{id:19,title:"Shapes in the Town",short:"Shapes",parts:[{title:"Name It and Place It",std:["K.G.A.1"],n:4,dur:70,dir:"Look at the house at night. Answer out loud.",desc:"naming the shapes of things in a scene and telling where they are with position words",fig:()=>F.row(shapeHouseFig()),qs:["What shape is the purple roof?","What shape is the blue window?","What shape is the yellow moon, and where is it compared to the house?","Where is the lantern pole compared to the house?"],key:["A triangle","A square","A circle, and it is above the house. Both halves are needed.","Beside the house, or next to the house, or to the right of the house. Any of those position words counts. Behind or in front of does not fit this picture."]},{title:"Flat or Solid",std:["K.G.A.3"],n:3,dur:65,dir:"Look at the four cards. Answer out loud.",desc:"telling two-dimensional (flat) shapes from three-dimensional (solid) ones",fig:()=>F.row(flatSolidFig()),qs:["Which two cards show a flat shape, one that is drawn flat on the card?","Which two cards show a solid shape, one you could pick up and hold?","Card 4 is a can. Is a can flat or solid? How do you know?"],key:["Cards 1 and 3, the yellow circle and the green triangle.","Cards 2 and 4, the blue box and the orange can.","Solid. Look for a reason about thickness or holding it: you could pick it up, it is fat, it has a top and sides you can see, it is not just a line drawn on paper."]}]},{id:20,title:"What Living Things Need",short:"Living Things",parts:[{std:["K-LS1-1"],n:3,dur:75,dir:"Look at both pictures. Answer out loud.",desc:"telling what an animal and a plant need to stay alive",html:()=>`<p class="big">Wren is starting a bean seed in a cup on the windowsill. An owl lives in the big pine across the street.</p>
     <div class="figure">${ic("sprout",96)}${ic("owl",96)}</div>`,qs:["A bean seed in a cup starts to grow when it gets two of these. Which two? Water, light, or a sticker?","The owl in the pine stays alive by getting two of these. Which two? Mice to eat, water to drink, or a bell?","Wren put one of her bean cups in a dark closet and forgot about it. That one never grew. What was it missing?"],key:["water and light. A sticker is not something a plant needs.","mice to eat and water to drink. A bell is not something an owl needs.","light. The cup had water but no light, so light is the thing that was missing. This is a pattern drawn from two cups that were treated differently, which is what the standard asks for."]}]},{id:21,title:"Weather in Town",short:"Weather",parts:[{std:["K-ESS2-1"],n:3,dur:75,dir:"Look at the four weeks. Count out loud.",desc:"describing a weather pattern across four weeks of recorded observations",html:()=>`<p class="big">All month the town kept a count of the rainy days, one week at a time.</p>
     <table class="chart bigTable" style="margin:14px auto;font-size:1.3rem">
     <tr><th>Week 1</th><td>${ic("rain",46)}${ic("rain",46)}</td></tr>
     <tr><th>Week 2</th><td>${ic("rain",46)}${ic("rain",46)}${ic("rain",46)}${ic("rain",46)}${ic("rain",46)}</td></tr>
     <tr><th>Week 3</th><td>${ic("rain",46)}</td></tr>
     <tr><th>Week 4</th><td>${ic("rain",46)}${ic("rain",46)}${ic("rain",46)}${ic("rain",46)}</td></tr></table>`,qs:["Which week had the most rainy days? How many?","Which week had the fewest rainy days? How many?","A friend is coming to visit next week. Would you tell your friend to pack an umbrella? Why?"],key:["Week 2, with 5 rainy days","Week 3, with 1 rainy day","Yes, because it rained in every single week this month. Any answer that points at the whole month and not at one day counts. Describing the pattern is the check here, not the yes or no."]},{std:["K-ESS2-2"],n:2,dur:60,dir:"Answer out loud.",desc:"telling how a living thing changes its surroundings",html:()=>`<p class="big">A big pine grows right beside the brick path to the bridge.</p>
     <div class="figure">${ic("pine",88)}${ic("bridge",88)}</div>`,qs:["The roots of the pine have pushed the bricks of the path up into a bump. Did the tree change the path, or did the path change the tree?","Tell me one way a person changes the ground when they want to start a garden."],key:["The tree changed the path. Its roots grew and lifted the bricks, and the bricks were flat before.","Any sensible answer: digs it up, pulls out the weeds, rakes it smooth, makes rows, adds soil, builds a box to hold the soil."]}]},{id:22,title:"Homes, Forecasts and the Land",short:"Homes",parts:[{std:["K-ESS3-1"],n:3,dur:75,dir:"Match each animal to the place it lives. Answer out loud.",desc:"matching animals to the places that give them what they need",html:()=>`<p class="big">Three animals live near the bridge. Each one lives in one place. It gets what it needs.</p>
     <div class="figure">${ic("mouse",80)}${ic("owl",80)}${ic("duck",80)}</div>
     <p class="big">Here are the places. A hole in the ground. It is under the woodpile. A hollow in a tree. It is high up. The pond.</p>`,qs:["Where does the mouse live?","Where does the owl live?","Where does the duck live?"],key:["a hole in the ground under the woodpile. Accept a burrow or a nest in the ground.","a hollow high up in a tree","the pond. Accept the water."]},{std:["K-ESS3-2"],n:2,dur:60,dir:"Answer out loud.",desc:"telling what a weather forecast is for and how people use one to get ready",html:()=>`<p class="big">The town reads the forecast for tonight before it gets dark.</p>
     <div class="figure">${ic("thermometer",88)}${ic("lamp",88)}</div>`,qs:["The forecast says the air will drop below freezing tonight and the bridge will go icy. Should the town spread sand on the bridge before dark, or wait until somebody slips in the morning?","Who would really want to hear a forecast: somebody who left young plants outside, or somebody picking a favorite number?"],key:["spread the sand before dark. A forecast is useful because it comes before the weather does.","somebody who left young plants outside. Follow up out loud: what would that person do after hearing it? Covering the plants or bringing them in both count."]},{std:["K-ESS3-3"],n:2,dur:60,dir:"Answer out loud.",desc:"telling one way people can take better care of the land and water",html:()=>`<p class="big">The creek runs under the bridge and out past the houses.</p>
     <div class="figure">${ic("leaf",96)}${ic("drop",96)}</div>`,qs:["Two neighbors rake their leaves. One sweeps the whole pile down the storm drain that runs to the creek. One piles the leaves in a corner of the yard to rot down into soil. Which choice is better for the creek?","Tell me one way your family could make less trash this year."],key:["piling the leaves in the yard. What goes down the drain ends up in the creek.","Any sensible answer: carry a lunch box instead of bags, reuse a bag, fix something instead of throwing it out, pass clothes on to somebody smaller, put cans and paper in recycling, take a cup from home."]}]},{id:23,title:"Pushes and Pulls in the Park",short:"Push and Pull",parts:[{std:["K-PS2-1"],n:3,dur:75,dir:"Answer out loud. Do not say push or pull for the student.",desc:"telling a push from a pull, and comparing a strong push with a gentle one",html:()=>`<p class="big">A push moves something away from you. A pull brings it toward you.</p>
     <div class="figure">${ic("cabin",88)}${ic("box",88)}</div>`,qs:["Theo sits on the park swing. Wren stands behind him and sends him away from her. Is that a push or a pull?","Wren opens the shed door by taking the handle and bringing it toward her. Is that a push or a pull?","Theo gets a gentle send on the swing and goes a little way. Then he gets a strong one. What is different about the way he swings?"],key:["a push","a pull","He swings higher and farther. A stronger push moves a thing farther."]},{std:["K-PS2-2"],n:2,dur:60,dir:"Look at the chart. Answer out loud.",desc:"deciding from test results whether a push changed how far a thing moved, and whether something changed its direction",html:()=>`<p class="big">Wren set up six blocks in a row and rolled the same ball at them twice. She counted the blocks that fell.</p>
     <table class="chart bigTable" style="margin:14px auto;font-size:1.3rem"><tr><th>Roll</th><th style="text-align:center">Blocks that fell</th></tr>
     <tr><td>a gentle roll</td><td>1</td></tr><tr><td>a strong roll</td><td>6</td></tr></table>`,qs:["Which roll knocked down more blocks, and how many?","Another ball is rolling straight down the sidewalk. Theo holds a board out on one side of it. The ball hits the board and goes off a new way. Did the board change where the ball was going?"],key:["the strong roll, 6 blocks. The gentle roll only knocked down 1.","Yes. It changed the direction the ball was going. Accept it turned it, it sent it sideways, it bounced it."]}]},{id:24,title:"Sun and Shade on the Street",short:"Sun",parts:[{std:["K-PS3-1"],n:2,dur:60,dir:"Answer out loud. If you can, feel a sunny spot and a shady spot together first.",desc:"telling what sunlight does to a surface it shines on",html:()=>`<p class="big">Here are two cups of water. The water is cold. Both were set out. They sit on the porch. Both went out together. The time was the same. One sits in the open sunlight. One sits in the shadow. The railing makes it.</p>
     <div class="figure">${ic("sun",88)}${ic("drop",88)}</div>`,qs:["By the middle of the day one cup has warm water in it. Which one, the cup in the sunlight or the cup in the shadow?","The bench on the sunny side of the street has no frost left on it. The bench in the shadow still has frost. The two benches are exactly the same. What made the difference?"],key:["the cup in the open sunlight","the sunlight. One bench got sunlight on it and the other did not, so the sunlight is what warmed the first bench and melted its frost."]},{std:["K-PS3-2"],n:2,dur:75,dir:"Draw your answer on your paper and hold it up.",desc:"designing and drawing a cover that keeps a spot out of the sunlight",html:()=>`<p class="big">Wren's cups hold new sprouts. They sit on the windowsill. The afternoon sunlight pours straight in. The little sprouts go limp. Draw something that keeps the afternoon sunlight off the cups, like a paper screen, a curtain, or a flap of cardboard that stands up.</p>
     <div class="figure">${ic("sprout",88)}${ic("cabin",88)}</div>`,qs:["Draw your shade for the cups of sprouts.","Point to where the sunlight comes in and tell me how your shade keeps the cups cooler."],key:["Any cover drawn BETWEEN the window and the cups, or above them. The three examples are in the direction, so copying one still counts. A cover drawn behind the cups is partial: ask which way the sunlight comes in.","Something like: it blocks the sun, the sun cannot get to them, it puts them in a shadow."]}]},{id:25,title:"Solving a Problem in Town",short:"Solve It",parts:[{std:["K-2-ETS1-1"],n:2,dur:60,dir:"Listen, then answer out loud.",desc:"naming a problem people want to fix and asking a question about it",read:"The town pins its notices on a flat wooden board by the bridge, so everybody knows what is coming up. The board has nothing over the top of it. Every time it rains, the paper notices soak through and the writing runs, and nobody can read a single one.",qs:["What is the problem? The rain soaks the notices, or the board is made of wood?","Ask me one question about the board that would help you fix this."],key:["The rain soaks the notices and nobody can read them.","Any real question: how big is the board, which way does the rain come in, how many notices go up, is there a roof anywhere nearby, could the paper be covered. A statement is not a question, so ask once more."]},{std:["K-2-ETS1-2"],n:2,dur:75,dir:"Draw your answer on your paper and hold it up.",desc:"drawing something whose shape would solve the problem",html:()=>`<p class="big">Draw something that would keep the notices dry, like a little slanted roof over the board, a clear flap that lifts, or a box with a lid on the front.</p>
     <div class="figure">${ic("box",88)}${ic("rain",88)}</div>`,qs:["Draw your fix.","Tell me what you drew and how its shape keeps the rain off the paper."],key:["Anything that would turn rain away from the paper: a roof or ledge above it, a slanted top, a clear sheet over the front, a lid, a case. The three examples are in the direction, so copying one earns credit.","Naming it is what shows intent. Something like: the roof sends the rain off the side, the flap covers the paper, the lid shuts the rain out."]},{std:["K-2-ETS1-3"],n:2,dur:60,dir:"Look at the chart. Answer out loud.",desc:"comparing test results from two fixes for the same problem",html:()=>`<p class="big">The town put up 10 notices, tried two fixes, and counted how many were still dry after the rain.</p>
     <table class="chart bigTable" style="margin:14px auto;font-size:1.3rem"><tr><th>Fix</th><th style="text-align:center">Notices still dry</th></tr>
     <tr><td>a slanted roof over the whole board</td><td>8</td></tr><tr><td>a strip of tape along the top edge</td><td>3</td></tr></table>`,qs:["Which fix worked better?","How do you know?"],key:["the slanted roof over the whole board","Because 8 notices stayed dry under the roof and only 3 stayed dry with the tape. The reason has to come from the chart, not from liking roofs."]}]},{id:26,title:"Rules and Doing Right",short:"Rules",parts:[{std:["HSS-K.1"],n:3,dur:75,dir:"Listen, then answer out loud.",desc:"following rules, knowing what happens when they are broken, and naming an honest choice",read:"At the end of the day Theo was counting the chalk sticks back into the tin. One of them was already in his pocket, because he had meant to take it home. He stood there a moment. Then he took it out, dropped it in the tin, and said to his teacher, I almost took one home with me. His teacher said, thank you for putting it back.",qs:["What did Theo choose to do? Put the chalk back and say so, or leave it in his pocket and say nothing?","One rule at the park is wait your turn at the ladder. What might go wrong if nobody waited their turn?","Think of one rule in your classroom. What would be hard if that rule went away?"],key:["He put the chalk back and said so.","Somebody gets bumped or pushed, it stops being safe, children argue, somebody never gets a turn. Any real consequence counts.","Any rule with a real consequence attached. The consequence is the part to listen for, not the rule."]}]},{id:27,title:"Maps and Places",short:"Maps",parts:[{std:["HSS-K.4"],n:4,dur:90,dir:"Look at the map. Answer out loud.",desc:"reading map symbols, telling land from water, and naming places in a town",html:()=>`<p class="big">Here is a map. It shows the town. The blue line is the creek. It runs down the middle. The gray lines are roads. The school is on one side. The creek runs between. The other side has the park. One bridge crosses between them.</p>
     <div class="figure"><svg viewBox="0 0 300 180" width="300" height="180" role="img" aria-label="A map showing water around an island with a house and a tree"><rect x="2" y="2" width="296" height="176" rx="14" fill="#BFE3F5" stroke="#6B4A3C" stroke-width="3"/><g stroke="#5E8FA8" stroke-width="3" stroke-linecap="round" fill="none"><path d="M22 34 q10 -8 20 0 t20 0"/><path d="M232 34 q10 -8 20 0 t20 0"/><path d="M22 150 q10 -8 20 0 t20 0"/><path d="M232 150 q10 -8 20 0 t20 0"/><path d="M22 92 q10 -8 20 0 t20 0"/><path d="M232 92 q10 -8 20 0 t20 0"/></g><ellipse cx="150" cy="90" rx="92" ry="54" fill="#A8D49A" stroke="#6B4A3C" stroke-width="3"/><g transform="translate(110,92)"><rect x="-20" y="-6" width="40" height="32" rx="4" fill="#F2E3C6" stroke="#6B4A3C" stroke-width="3"/><path d="M-26 -6 L0 -28 L26 -6 Z" fill="#D9704F" stroke="#6B4A3C" stroke-width="3" stroke-linejoin="round"/><rect x="-7" y="8" width="14" height="18" rx="2" fill="#A8724E" stroke="#6B4A3C" stroke-width="2.4"/></g><g transform="translate(192,92)"><rect x="-6" y="2" width="12" height="24" rx="3" fill="#A8724E" stroke="#6B4A3C" stroke-width="2.6"/><circle cx="0" cy="-8" r="22" fill="#6FB762" stroke="#6B4A3C" stroke-width="3"/></g></svg></div>
     <p class="big">${ic("cabin",56)} the school &nbsp;&nbsp; ${ic("bridge",56)} the bridge &nbsp;&nbsp; ${ic("tree",56)} the park</p>`,qs:["On this map, which part is the water and which parts are the roads?","The bridge crosses the creek. Is the bridge over the water or under the water?","The school is on one side of the creek. Is the park on the same side as the school, or on the other side?","Name two places in your own town that you could walk to."],key:["The blue line is the water, which is the creek. The gray lines are the roads.","over the water","on the other side. That is why the town needs the bridge.","Any two real places: a store, a library, a park, a mailbox, a school, a neighbor's house. The moon does not count."]}]},{id:28,title:"Our Flag and Long Ago",short:"Long Ago",parts:[{std:["HSS-K.2"],n:2,dur:60,dir:"Look at both pictures. Answer out loud.",desc:"recognizing national symbols of the country",html:()=>`<div class="figure">${ic("flag",110)}${ic("eagle",110)}</div>`,qs:["One of these is our country's flag. Which one is it?","The other one is a bald eagle, and that is a symbol of our country too. Name one place where you have seen our flag."],key:["the one with the stars and stripes. Accept pointing. Accept the flag of our country or the American flag.","Any real place: a school, a post office, a park, outside a building, on a coin, at a game."]},{std:["HSS-K.6"],n:3,dur:75,dir:"Answer out loud.",desc:"telling how life long ago was different from life today, and what a commemorative holiday is for",html:()=>`<p class="big">Long ago there were no electric lights in a house.</p>
     <div class="figure">${ic("lantern",96)}${ic("lamp",96)}</div>`,qs:["Long ago, what did a family use to see after dark, an oil lantern they had to fill and light, or a lamp you switch on?","How does a light come on in your house today?","Independence Day comes back every year and the whole country marks it together. Is a day like that about something that has already happened, or about something that has not happened yet?"],key:["an oil lantern they had to fill and light","Any real answer: a switch on the wall, a button, a cord you pull, a lamp you plug in, asking a speaker to turn it on. Naming today's way is the then-and-now half of this standard.","something that has already happened. Follow up: what do you think the country is remembering? Any reasonable answer counts at this age."]}]}];const LEVELUPS={1:{id:"L1",lv:true,title:"Level Up: Sentence Parts",std:["RF.1.1"],needs:["RF.K.1"],n:3,dir:"Look at the sentence. Answer out loud.",html:()=>`<p class="passage" style="font-size:2.4rem;text-align:center;margin:0 auto;width:fit-content">We walk to the bridge.</p><ol class="qlist"><li>Which word is the first word of the sentence?</li><li>Why does that word start with a big letter?</li><li>What mark is at the end of the sentence?</li></ol>`,key:["We","Because it is the first word of the sentence. Sentences start with a capital letter.","A period, or a dot"]},2:{id:"L2",lv:true,title:"Level Up: Count to 120",std:["1.NBT.A.1"],needs:["K.CC.A.1"],n:2,dir:"Count out loud. Then read the numbers.",html:()=>`<ol class="qlist"><li>Start at 108. Count out loud to 116.</li><li>Read each number.</li></ol>${wordGrid(["47","103","118"])}`,key:["108, 109, 110, 111, 112, 113, 114, 115, 116 with no skips. Listen at 109 to 110.","Reads forty-seven, one hundred three, one hundred eighteen"]},4:{id:"L4",lv:true,title:"Level Up: Read a Story",std:["RL.1.1"],needs:["RL.K.1"],n:2,dir:"Read the story out loud. Then answer out loud.",html:()=>`<p class="passage" style="font-size:2rem;line-height:1.8">Juno put on her coat and ran out to the rope. The last lantern was still dark. She stood on a box and reached up high. Then the lantern came on, and the whole street glowed.</p><ol class="qlist"><li>What did Juno stand on?</li><li>What happened after the last lantern came on?</li></ol>`,key:["A box","The whole street glowed"]},6:{id:"L6",lv:true,title:"Level Up: Tricky Words",std:["RF.1.3"],needs:["RF.K.3"],n:3,dir:"Read each word out loud.",html:()=>wordGrid(["chin","when","note"]),key:["Reads the first word (ch digraph, short i)","Reads the second word (wh digraph, short e)","Reads the third word (final e, long o)"]},10:{id:"L10",lv:true,title:"Level Up: Measure It",std:["1.MD.A.2"],needs:["K.MD.A.2"],n:3,dir:"Look at the blocks under the rope and the pole. Answer out loud.",html:()=>`<div class="figure">${unitFig()}</div><ol class="qlist"><li>How many blocks long is the rope?</li><li>How many blocks long is the pole?</li><li>Why do the blocks have to touch, with no gaps?</li></ol>`,key:["5 blocks","3 blocks","Because a gap would make the count wrong. The blocks must sit end to end with no gaps and no overlaps."]}};let npOn={},tfOn={};function npHtml(){let h=`<div class="nl">`;for(let i=1;i<=40;i++)h+=`<button data-n="${i}" class="${npOn[i]?"on":""}">${i}</button>`;return h+`</div><p class="small">Click a number to mark it. Click it again to clear.</p>`}function tfHtml(){return`<div class="tf-wrap">`+[0,1].map(f=>{let c=`<div class="tf">`;for(let i=0;i<10;i++){const k=f*10+i;c+=`<button data-k="${k}" class="c${tfOn[k]||0}" aria-label="Box ${k+1}"><span></span></button>`}return c+"</div>"}).join("")+`</div><p class="small">Click a box to add a red counter. Click again for yellow. Click again to clear.</p>`}const STARTERS={opinion:["I would pick ____.","I like it because ____.","That is why I would pick it."],facts:["This is a ____.","It is ____.","One true thing is ____."],story:["One night I ____.","First, ____.","Then, ____.","I felt ____."]};function sentHtml(st){const wk=st&&st.parts&&st.parts[0]&&st.parts[0].wk||"facts";return`<ul class="starters">${(STARTERS[wk]||STARTERS.facts).map(x=>`<li>${x}</li>`).join("")}</ul>`}function tpsCmpHtml(){const bar=(y,w,fill,lab2)=>`<rect x="46" y="${y}" width="${w}" height="26" rx="7" fill="${fill}" stroke="var(--fig-ink)" stroke-width="2.5"/><text x="${54+w}" y="${y+14}" font-size="17" dominant-baseline="central" fill="var(--ink)">${lab2}</text>`;const svg=`<svg viewBox="0 0 370 128" width="350" style="max-width:100%" role="img" aria-label="Two bars that both start at the same line. The top bar is longer and the bottom bar is shorter."><line x1="46" y1="14" x2="46" y2="110" stroke="var(--fig-ink)" stroke-width="3" stroke-dasharray="6 5"/>${bar(28,196,"var(--gold)","longer")}${bar(74,112,"var(--gold)","shorter")}<text x="46" y="124" font-size="14" text-anchor="middle" fill="var(--muted)">start</text></svg>`;return`<div class="figure">${svg}</div>`+F.table(["Word","What it means"],[["longer","it goes past the other one"],["shorter","it stops before the other one"],["taller","it goes higher than the other one"],["the same","they both end in the same place"]])+`<p class="small">Line both things up at the same start line. Then look at the other end to see which one goes further.</p>`}const tpsIco=(n,px)=>(F.icon||F.pic2)(n,px)||"";const TPS_ABC=[["a","apple","apple"],["b","bear","bear"],["c","cat","cat"],["d","dog","dog"],["e","egg","egg"],["f","fish","fish"],["g","goat","goat"],["h","hen","hen"],["i","island","island"],["j","jam",""],["k","key","key"],["l","leaf","leaf"],["m","moon","moon"],["n","nose","nose"],["o","octopus","octopus"],["p","pig","pig"],["q","queen",""],["r","rabbit","rabbit"],["s","sun","sun"],["t","tent","tent"],["u","umbrella","umbrella"],["v","van",""],["w","wave","wave"],["x","box, x at the end","box"],["y","yarn",""],["z","zip",""]];function tpsLetterHtml(){const cell=c=>`<div style="display:flex;flex-direction:column;align-items:center;gap:2px;min-width:70px;padding:6px 4px;border:2px solid var(--line);border-radius:10px"><b style="font-size:1.45rem;line-height:1">${c[0]} ${c[0].toUpperCase()}</b>${c[2]?tpsIco(c[2],30):""}<span style="font-size:.9rem;text-align:center">${c[1]}</span></div>`;return`<div class="tool-scroll"><div style="display:flex;flex-wrap:wrap;gap:6px;justify-content:center">${TPS_ABC.map(cell).join("")}</div></div><ul class="frames"><li>Point to a letter and ask for its sound, not its name.</li><li>Rhyme: two words that end with the same sounds, like cat and hat.</li><li>Word parts: clap once for each part you hear. Cam-per is two claps.</li><li>First sound: say only the sound at the start of the word.</li></ul>`}function tpsRetellHtml(){return F.table(["Part","What to tell","Starter"],[["1. First","who was there and where it was","First, ____."],["2. Next","what happened","Then, ____."],["3. Last","how it ended","Last, ____."]])+`<p class="small">Tell the three parts in that order. The card gives the order words, so the student supplies what happened.</p>`}function tpsQwordHtml(){return F.table(["Question word","What it asks about","A question you could ask"],[["Who","a person or an animal","Who helped?"],["What","a thing, or what happened","What did she find?"],["Where","a place","Where did they go?"],["When","a time","When did it start?"],["Why","a reason","Why did it happen?"],["How","the way something is done","How did they fix it?"]])+`<p class="small">Start with one of these words. A question ends with a question mark, and your voice goes up at the end.</p>`}let tpsMaskIdx=0;function tpsMaskLines(){const el=document.querySelector("#stopView .passage");if(!el)return null;const d=document.createElement("div");d.innerHTML=el.innerHTML.replace(/<br\s*\/?>/gi,"\n");const flat=(d.textContent||"").replace(/[ \t]+/g," ");let out=flat.split("\n").map(s=>s.trim()).filter(Boolean);if(out.length<2)out=flat.split(/(?<=[.!?\u201D])\s+/).map(s=>s.trim()).filter(Boolean);return out.length?out:null}function tpsMaskHtml(){const L=tpsMaskLines();if(!L)return`<p class="small">This stop has no passage on the screen to window. Lay a card under the line the student is reading and slide it down one line at a time.</p>`;if(tpsMaskIdx>=L.length)tpsMaskIdx=L.length-1;return`<div class="row center"><button class="chip" data-m="-1">Back</button><button class="chip" data-m="1">Next</button><button class="chip" data-m="0">Start over</button></div><p style="font-family:var(--font-display);font-size:clamp(1.3rem,3.2vw,2rem);line-height:1.6;text-align:center;margin:12px 0">${F.esc(L[tpsMaskIdx])}</p><p class="small">Line ${tpsMaskIdx+1} of ${L.length}. The whole passage stays on the student page. This window is for a student who loses their place, and it reads the first passage on the stop.</p>`}function tpsMaskBind(b,r){b.querySelectorAll("[data-m]").forEach(x=>x.onclick=()=>{const n=(tpsMaskLines()||[""]).length,d=+x.dataset.m;tpsMaskIdx=d?Math.max(0,Math.min(n-1,tpsMaskIdx+d)):0;r()})}const TOOLS={np:{name:"Number line 0 to 20",std:["1.NBT.A.1","1.NBT.B.2","1.OA.A.1","K.CC.A.1","K.CC.B.4","K.CC.C.6","K.MD.B.3","K.NBT.A.1","K.OA.A.2","K.OA.A.3"],html:()=>window.TPNL20(),bind:(b,r)=>window.TPNL20Bind(b,r)},tf:{name:"Ten frames",std:["1.MD.C.4","1.NBT.B.2","1.OA.A.1","K.CC.B.4","K.CC.C.6","K.MD.B.3","K.NBT.A.1","K.OA.A.2","K.OA.A.3"],html:tfHtml,bind:(b,r)=>b.querySelectorAll("[data-k]").forEach(x=>x.onclick=()=>{tfOn[x.dataset.k]=((tfOn[x.dataset.k]||0)+1)%3;r()})},sent:{name:"Sentence starters",std:["W.K.1","W.K.2","W.K.3","W.K.8"],html:sentHtml},cmp:{name:"Longer and shorter card",std:["K.MD.A.2"],html:tpsCmpHtml},letters:{name:"Letter and sound card",std:["RF.K.1","RF.K.2","RF.K.3"],html:tpsLetterHtml},retell:{name:"First, next, last card",std:["SL.K.4","W.K.3"],html:tpsRetellHtml},qwords:{name:"Question word card",std:["K-2-ETS1-1","L.K.1","RI.K.1","RL.K.1","SL.K.2"],html:tpsQwordHtml},mask:{name:"Reading window (one line at a time)",std:["RF.K.4"],html:tpsMaskHtml,bind:tpsMaskBind}};const SUP_CAVEATS=[{t:"np",std:["K.CC.A.1"],msg:"The number line shows the counting order, so counting done with it is supported, not independent."},{t:"np",std:["K.OA.A.2"],msg:"If the student counted up or back along the number line, note that the answer came from a visual, not from knowing the combination."},{t:"tf",std:["K.OA.A.3"],msg:"The ten frame is a fine way to show a number broken into two parts. Note whether the student found the second way without you moving counters."},{t:"np",std:["K.CC.B.4"],msg:"The number line shows the counting order, so a count made along it is supported. Note whether the student could say how many without going back to the path."},{t:"tf",std:["K.NBT.A.1"],msg:"Filling one ten frame and then the extras shows the ten and some more for the student. Note that the teen number was built with a model you supplied."},{t:"tf",std:["K.MD.B.3"],msg:"If each sorted group was parked on the ten frame before counting, the student sorted with a model you built. Note it."},{t:"sent",msg:"Sentence starters give the student the opening words, so count those checks as supported, not independent."},{t:"passage",std:["RF.K.4"],msg:"If the lines on the screen were read to the student, this part shows listening, not reading. Rate it only if the student read the lines."},{t:"scribe",std:["W.K.1","W.K.2","W.K.3"],msg:"Telling an adult what to write is allowed at this grade. Note it, and do not rate the printing from this stop."},{t:"cmp",std:["K.MD.A.2"],msg:"The card supplies the words longer, shorter and taller, so rate on whether the student picks the right one, not on producing the word."},{t:"letters",std:["RF.K.1","RF.K.3"],msg:"The letter and sound card shows a keyword and a picture for each letter, so a sound read off the card is supported, not known by heart."},{t:"letters",std:["RF.K.2"],msg:"RF.K.2 is listening only. If the card was open, note that the student had the rhyme and the clapping rule in front of them."},{t:"retell",std:["SL.K.4","W.K.3"],msg:"The card gives the order words first, then and last, so count the order as supported and rate the details the student supplies."},{t:"qwords",std:["RL.K.1","RI.K.1","L.K.1","SL.K.2","K-2-ETS1-1"],msg:"The card supplies the question words, so a question asked with it open shows the student can use a word that was given, not that they thought of one alone."},{t:"mask",std:["RF.K.4"],msg:"A read with the reading window open is not a clean fluency check. Note in the stop notes that the lines were shown one at a time."}];return{stops:STOPS,levelups:LEVELUPS,tools:TOOLS,supCaveats:SUP_CAVEATS,passageStd:["RF.K.4"],onLeaveStop:()=>{DECKS.forEach(d=>d.reset())}}}});
